const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '..');
const data = p => fs.readFileSync(path.join(root, p)).toString('base64');
// Read the same semantic tokens used by patient pages; never maintain a second palette.
const patientThemeSource = fs.readFileSync(path.join(root, 'lib/app/theme/patient_palette.dart'), 'utf8');
function patientCss(mode) {
  const block = patientThemeSource.match(new RegExp('static const ' + mode + ' = PatientPalette\\(([\\s\\S]*?)\\n  \\);'))?.[1];
  if (!block) throw new Error('Patient palette not found: ' + mode);
  const names = {blue:'action',link:'link',bg:'canvas',card:'card',ink:'text',muted:'textMuted',line:'divider',soft:'softAccent',onsoft:'onSoftAccent',green:'success',greenbg:'successContainer',red:'danger',redbg:'dangerContainer',amber:'warning',amberbg:'warningContainer'};
  return Object.entries(names).map(([css, dart]) => {
    const hex = block.match(new RegExp('\\b' + dart + ': Color\\(0xFF([0-9A-Fa-f]{6})\\)'))?.[1];
    if (!hex) throw new Error('Missing patient token: ' + dart);
    return '--' + css + ':#' + hex.toLowerCase();
  }).join(';');
}
