const users=[...patients.map((p,i)=>({id:p.id,name:p.name,email:['amina','omar','layla','khalid'][i]+'@example.test',type:'Patients',role:'Patient',dept:'—',active:i!==3,clinician:i<3?'Dr Ali Mansoor':'Dr Fatima Noor'})),...['Doctor','Nurse','Receptionist','Pharmacist','Dentist'].map((r,i)=>({id:'ST-00'+(i+1),name:['Ali Mansoor','Maryam Hasan','Huda Saleh','Yusuf Karim','Sara Abbas'][i],email:r.toLowerCase()+'@example.test',type:'Staff',role:r,dept:['Family medicine','Family medicine','Administration','Pharmacy','Dental'][i],active:true})),{id:'AD-001',name:'Huda Mahmood',email:'admin@example.test',type:'Admins',role:'Admin',dept:'—',active:true}];
