const receiptDays=Array.from({length:30},(_,i)=>({date:new Date(Date.UTC(2026,8,16+i)).toISOString().slice(0,10),pay:15000+(i%5)*12500,refund:i%3===0?5000:0}));
// 30 days ending at the fixed preview date; all money is integer fils.
receiptDays.forEach((r,i)=>{r.date=new Date(Date.UTC(2026,9,15-(29-i))).toISOString().slice(0,10)});
